<?php
declare(strict_types=1);
namespace App\Application\Review\Service;
use App\Application\Review\DTO\Request\CobitGameAnswersRequestDto;use App\Application\Review\DTO\Response\CobitGameResponseDto;use App\Application\Review\DTO\Response\CobitGameResultResponseDto;
final class CobitGameService { private const DOMAINS=[['id'=>'PO','code'=>'PO','name'=>'Planejar e Organizar'],['id'=>'AI','code'=>'AI','name'=>'Adquirir e Implementar'],['id'=>'DS','code'=>'DS','name'=>'Entregar e Suportar'],['id'=>'ME','code'=>'ME','name'=>'Monitorar e Avaliar']]; private const PROCESSES=[['id'=>'PO1','name'=>'Definir um plano estratégico de TI','domain'=>'PO'],['id'=>'PO2','name'=>'Definir a arquitetura da informação','domain'=>'PO'],['id'=>'PO3','name'=>'Determinar a direção tecnológica','domain'=>'PO'],['id'=>'PO4','name'=>'Definir processos, organização e relacionamentos de TI','domain'=>'PO'],['id'=>'PO5','name'=>'Gerenciar o investimento em TI','domain'=>'PO'],['id'=>'PO6','name'=>'Comunicar metas e direcionamentos gerenciais','domain'=>'PO'],['id'=>'PO7','name'=>'Gerenciar recursos humanos de TI','domain'=>'PO'],['id'=>'PO8','name'=>'Gerenciar qualidade','domain'=>'PO'],['id'=>'PO9','name'=>'Avaliar e gerenciar riscos de TI','domain'=>'PO'],['id'=>'PO10','name'=>'Gerenciar projetos','domain'=>'PO'],['id'=>'AI1','name'=>'Identificar soluções automatizadas','domain'=>'AI'],['id'=>'AI2','name'=>'Adquirir e manter softwares aplicativos','domain'=>'AI'],['id'=>'AI3','name'=>'Adquirir e manter infraestrutura tecnológica','domain'=>'AI'],['id'=>'AI4','name'=>'Viabilizar operação e uso','domain'=>'AI'],['id'=>'AI5','name'=>'Adquirir recursos de TI','domain'=>'AI'],['id'=>'AI6','name'=>'Gerenciar mudanças','domain'=>'AI'],['id'=>'AI7','name'=>'Instalar e homologar soluções e mudanças','domain'=>'AI'],['id'=>'DS1','name'=>'Definir e gerenciar níveis de serviço','domain'=>'DS'],['id'=>'DS2','name'=>'Gerenciar serviços de terceiros','domain'=>'DS'],['id'=>'DS3','name'=>'Gerenciar desempenho e capacidade','domain'=>'DS'],['id'=>'DS4','name'=>'Garantir continuidade dos serviços','domain'=>'DS'],['id'=>'DS5','name'=>'Garantir segurança dos sistemas','domain'=>'DS'],['id'=>'DS6','name'=>'Identificar e alocar custos','domain'=>'DS'],['id'=>'DS7','name'=>'Educar e treinar usuários','domain'=>'DS'],['id'=>'DS8','name'=>'Gerenciar central de serviços e incidentes','domain'=>'DS'],['id'=>'DS9','name'=>'Gerenciar configuração','domain'=>'DS'],['id'=>'DS10','name'=>'Gerenciar problemas','domain'=>'DS'],['id'=>'DS11','name'=>'Gerenciar dados','domain'=>'DS'],['id'=>'DS12','name'=>'Gerenciar ambiente físico','domain'=>'DS'],['id'=>'DS13','name'=>'Gerenciar operações','domain'=>'DS'],['id'=>'ME1','name'=>'Monitorar e avaliar o desempenho de TI','domain'=>'ME'],['id'=>'ME2','name'=>'Monitorar e avaliar controles internos','domain'=>'ME'],['id'=>'ME3','name'=>'Assegurar conformidade com requisitos externos','domain'=>'ME'],['id'=>'ME4','name'=>'Prover governança de TI','domain'=>'ME']]; public function exercise():CobitGameResponseDto{return new CobitGameResponseDto('COBIT 4.1 — Domínios e processos','Associe cada processo ao seu domínio.',self::DOMAINS,array_map(static fn(array $p):array=>['id'=>$p['id'],'name'=>$p['name']],self::PROCESSES));} public function evaluate(CobitGameAnswersRequestDto $request):CobitGameResultResponseDto{$answers=[];$correct=0;$expected=array_column(self::PROCESSES,'domain','id');foreach($request->answers as $answer){$process=$answer['processId'];if(!isset($expected[$process]))throw new \InvalidArgumentException('Processo inválido.');$isCorrect=$expected[$process]===$answer['domainId'];$correct+=(int)$isCorrect;$answers[]=['processId'=>$process,'correct'=>$isCorrect,'expectedDomainId'=>$expected[$process]];}if(count($answers)!==count(self::PROCESSES)||count(array_unique(array_column($answers,'processId')))!==count(self::PROCESSES))throw new \InvalidArgumentException('Responda todos os processos uma única vez.');return new CobitGameResultResponseDto($correct,count(self::PROCESSES),(int)round($correct/count(self::PROCESSES)*100),$answers);} }
